	}

	var filtered []mod.Module
	for _, m := range modules {
		if m.Main {
			continue
		}
		if directOnly && m.Indirect {
			continue
		}
		if updateOnly && m.Update == nil {
			continue
		}
		filtered = append(filtered, m)
	}

	if len(filtered) == 0 {
		return
	}

	renderTable(stdout, filtered, style)

	if ci {
		for _, m := range filtered {
			if m.Replace == nil && m.Update != nil {
				os.Exit(1)
			}
		}
	}
