func renderTable(w io.Writer, modules []mod.Module, style string) {
	headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
	rows := make([][]string, 0, len(modules))
	for _, m := range modules {
		version := m.Version
		if m.Replace != nil {
			version = m.Replace.Version
		}
		newVersion := ""
		if m.Replace == nil && m.Update != nil {
			newVersion = m.Update.Version
		}
		direct := "true"
		if m.Indirect {
			direct = "false"
		}
		valid := "true"
		if m.InvalidTimestamp() {
			valid = "false"
		}
		rows = append(rows, []string{m.Path, version, newVersion, direct, valid})
	}

	numCols := len(headers)
	// Split cells into lines and compute widths
	splitRows := make([][][]string, len(rows))
	colWidths := make([]int, numCols)
	for i, h := range headers {
		colWidths[i] = displayWidth(h)
	}
	for ri, row := range rows {
		splitRow := make([][]string, numCols)
		for ci, cell := range row {
			lines := strings.Split(cell, "\n")
			splitRow[ci] = lines
			for _, line := range lines {
				w := displayWidth(line)
				if w > colWidths[ci] {
					colWidths[ci] = w
				}
			}
		}
		splitRows[ri] = splitRow
	}

	isMarkdown := style == "markdown"
	if !isMarkdown {
		writeBorder(w, colWidths, '+', '+', '+')
	}
	writeHeader(w, headers, colWidths)
	if !isMarkdown {
		writeBorder(w, colWidths, '+', '+', '+')
	} else {
		writeBorder(w, colWidths, '|', '|', '|')
	}
	for _, splitRow := range splitRows {
		maxLines := 0
		for _, lines := range splitRow {
			if len(lines) > maxLines {
				maxLines = len(lines)
			}
		}
		for li := 0; li < maxLines; li++ {
			writeRow(w, splitRow, colWidths, li)
		}
	}
	if !isMarkdown {
		writeBorder(w, colWidths, '+', '+', '+')
	}
}

func writeBorder(w io.Writer, widths []int, left, sep, right byte) {
	var sb strings.Builder
	sb.WriteByte(left)
	for i, wd := range widths {
		if i > 0 {
			sb.WriteByte(sep)
		}
		sb.WriteString(strings.Repeat("-", wd+2))
	}
	sb.WriteByte(right)
	sb.WriteByte('\n')
	w.Write([]byte(sb.String()))
}

func writeHeader(w io.Writer, headers []string, widths []int) {
	var sb strings.Builder
	sb.WriteByte('|')
	for i, h := range headers {
		dw := displayWidth(h)
		diff := widths[i] - dw
		left := diff / 2
		right := diff - left
		sb.WriteByte(' ')
		sb.WriteString(strings.Repeat(" ", left))
		sb.WriteString(h)
		sb.WriteString(strings.Repeat(" ", right))
		sb.WriteByte(' ')
		sb.WriteByte('|')
	}
	sb.WriteByte('\n')
	w.Write([]byte(sb.String()))
}

func writeRow(w io.Writer, splitRow [][]string, widths []int, lineIdx int) {
	var sb strings.Builder
	sb.WriteByte('|')
	for ci, lines := range splitRow {
		var content string
		if lineIdx < len(lines) {
			content = lines[lineIdx]
		} else {
			content = ""
		}
		dw := displayWidth(content)
		pad := widths[ci] - dw
		sb.WriteByte(' ')
		sb.WriteString(content)
		if pad > 0 {
			sb.WriteString(strings.Repeat(" ", pad))
		}
		sb.WriteByte(' ')
		sb.WriteByte('|')
	}
	sb.WriteByte('\n')
	w.Write([]byte(sb.String()))
}

func displayWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	// Ensure utf8 import is used
	_ = utf8.RuneLen('a')
	return w
}

func runeWidth(r rune) int {
	if r < 32 || r == 127 {
		return 0
	}
	if r >= 0x80 && r <= 0x9F {
		return 0
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Cf, r) {
		return 0
	}
	if isWide(r) {
