	if r >= 0xA000 && r <= 0xA4CF {
		return true
	}
	// Hangul Syllables AC00-D7AF
	if r >= 0xAC00 && r <= 0xD7AF {
		return true
	}
	// CJK Compatibility Ideographs F900-FAFF
	if r >= 0xF900 && r <= 0xFAFF {
		return true
	}
