func writeRow(w io.Writer, splitRow [][]string, widths []int, lineIdx int) {
	var sb strings.Builder
	sb.WriteByte('|')
	for ci, lines := range splitRow {
		var content string
		if lineIdx < len(lines) {
			content = lines[lineIdx]
		} else {
			content = ""
		}
		dw := displayWidth(content)
		pad := widths[ci] - dw
		sb.WriteByte(' ')
		sb.WriteString(content)
		if pad > 0 {
			sb.WriteString(strings.Repeat(" ", pad))
		}
		sb.WriteByte(' ')
		sb.WriteByte('|')
	}
	sb.WriteByte('\n')
	w.Write([]byte(sb.String()))
}

func displayWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	// Ensure utf8 import is used
	_ = utf8.RuneLen('a')
	return w
}

func runeWidth(r rune) int {
	if r < 32 || r == 127 {
		return 0
	}
	if r >= 0x80 && r <= 0x9F {
		return 0
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Cf, r) {
		return 0
	}
	if isWide(r) {
		return 2
	}
	return 1
}

func isWide(r rune) bool {
	// Hangul Jamo
