	}
	// Yi  A000-A4CF
	if r >= 0xA000 && r <= 0xA4CF {
		return true
	}
	// Hangul Syllables AC00-D7AF
	if r >= 0xAC00 && r <= 0xD7AF {
		return true
	}
	// CJK Compatibility Ideographs F900-FAFF
	if r >= 0xF900 && r <= 0xFAFF {
		return true
	}
	// CJK Compatibility Forms FE30-FE4F, Small Form Variants FE50-FE6F partially
	if r >= 0xFE10 && r <= 0xFE19 {
		return true
	}
	if r >= 0xFE30 && r <= 0xFE6F {
