	}
	// Fullwidth FF00-FF60, FFE0-FFE6
	if r >= 0xFF00 && r <= 0xFF60 {
		return true
	}
	if r >= 0xFFE0 && r <= 0xFFE6 {
		return true
	}
	// CJK Ext B and beyond 20000-3FFFF
	if r >= 0x20000 && r <= 0x3FFFF {
		return true
	}
	// Emoji and symbols: many in 1F300-1FAFF wide
	if r >= 0x1F300 && r <= 0x1FAFF {
		return true
	}
	// Misc symbols that are wide in runewidth: 231A-231B, 2329-232A, 23E9-23EC, etc.
	// Approximate: 2300-27BF some wide, but not all. For simplicity, treat some as wide:
	// We'll include common wide symbols
